<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>BREACHPOINT: DOCKSIDE — a three.js tactical FPS</title>
<style>
  /* Palette: cold slate + signal orange. Six UI colours, monospace readouts, hairline panels. */
  :root {
    --canvas: #0e1420;
    --panel: #161b22;
    --hairline: #2c323a;
    --ink: #e9e6df;
    --muted: #98a0a8;
    --accent: #ff7a1a;
    --good: #36c98f;
    --bad: #d93636;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
  }
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; overflow: hidden; background: var(--canvas); color: var(--ink); font-family: var(--font-ui); }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; user-select: none; }

  /* Crosshair: 4 ticks whose gap grows with spread via --gap set from JS. */
  #crosshair { position: fixed; left: 50%; top: 50%; width: 40px; height: 40px; transform: translate(-50%,-50%); }
  #crosshair i { position: absolute; background: var(--ink); opacity: .9; box-shadow: 0 0 3px rgba(0,0,0,.8); }
  #crosshair i:nth-child(1) { left: 19px; top: calc(10px - var(--gap, 0px)); width: 2px; height: 8px; }
  #crosshair i:nth-child(2) { left: 19px; bottom: calc(10px - var(--gap, 0px)); width: 2px; height: 8px; }
  #crosshair i:nth-child(3) { top: 19px; left: calc(10px - var(--gap, 0px)); height: 2px; width: 8px; }
  #crosshair i:nth-child(4) { top: 19px; right: calc(10px - var(--gap, 0px)); height: 2px; width: 8px; }
  #crosshair .dot { position: absolute; left: 19px; top: 19px; width: 2px; height: 2px; background: var(--ink); }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 30px; height: 30px; transform: translate(-50%,-50%) rotate(45deg); opacity: 0; transition: opacity 80ms linear; }
  #hitmarker.on { opacity: 1; }
  #hitmarker i { position: absolute; background: var(--ink); }
  #hitmarker.kill i { background: var(--accent); }
  #hitmarker i:nth-child(1) { left: 14px; top: 0; width: 2px; height: 9px; }
  #hitmarker i:nth-child(2) { left: 14px; bottom: 0; width: 2px; height: 9px; }
  #hitmarker i:nth-child(3) { top: 14px; left: 0; height: 2px; width: 9px; }
  #hitmarker i:nth-child(4) { top: 14px; right: 0; height: 2px; width: 9px; }

  /* Vignette: damage flash + low health pulse. */
  #vignette { position: fixed; inset: 0; opacity: 0; transition: opacity 140ms linear;
    background: radial-gradient(ellipse at center, transparent 42%, rgba(200,30,30,.55) 100%); }
  #vignette.persistent { animation: pulse 1.1s ease-in-out infinite; opacity: .5; }
  @keyframes pulse { 0%,100% { opacity: .3; } 50% { opacity: .7; } }

  /* Scope: black overlay with a circular cutout + hairlines. */
  #scope { position: fixed; inset: 0; opacity: 0; pointer-events: none; transition: opacity 90ms linear;
    background: radial-gradient(circle at center, transparent 26%, rgba(4,6,10,.985) 27.5%); }
  #scope.on { opacity: 1; }
  #scope::before, #scope::after { content: ''; position: fixed; left: 50%; top: 50%; background: rgba(233,230,223,.6); }
  #scope::before { width: 56vmin; height: 1px; transform: translate(-50%,-50%); }
  #scope::after { height: 56vmin; width: 1px; transform: translate(-50%,-50%); }

  /* Top bar: timer + round score + money. */
  #topbar { position: fixed; top: 14px; left: 50%; transform: translateX(-50%); display: flex; align-items: stretch; gap: 0;
    background: color-mix(in srgb, var(--panel) 84%, transparent); border: 1px solid var(--hairline); border-radius: 6px; }
  #topbar > div { padding: 8px 16px; display: flex; flex-direction: column; align-items: center; gap: 2px; }
  #topbar .label { font-size: 10px; letter-spacing: .14em; color: var(--muted); text-transform: uppercase; }
  #timer { font-family: var(--font-readout); font-size: 26px; line-height: 1; }
  #score-you { font-family: var(--font-readout); font-size: 26px; color: var(--good); line-height: 1; }
  #score-enemy { font-family: var(--font-readout); font-size: 26px; color: var(--bad); line-height: 1; }
  #money { font-family: var(--font-readout); font-size: 18px; color: var(--accent); line-height: 1; padding-top: 4px; }
  #round-pips { display: flex; gap: 4px; align-items: center; }
  #round-pips i { width: 8px; height: 8px; border-radius: 2px; background: var(--hairline); display: inline-block; }
  #round-pips i.you { background: var(--good); }
  #round-pips i.them { background: var(--bad); }
  #round-pips .vs { color: var(--muted); font-size: 10px; margin: 0 4px; }
  .sep { width: 1px; background: var(--hairline); }

  /* Bottom left: health + armor. */
  #vitals { position: fixed; left: 28px; bottom: 26px; width: 240px; }
  #vitals .row { display: flex; align-items: baseline; gap: 10px; }
  #health { font-family: var(--font-readout); font-size: 44px; line-height: 1; }
  .bar { height: 5px; background: rgba(255,255,255,.09); border-radius: 2px; overflow: hidden; margin-top: 6px; }
  #health-bar { height: 100%; width: 100%; background: var(--good); transition: width 120ms linear; }
  #armor-bar { height: 100%; width: 0%; background: #6ea8d8; transition: width 120ms linear; }
  #vitals .armor-row { margin-top: 5px; }

  /* Bottom right: weapon + ammo + grenades. */
  #weapon-box { position: fixed; right: 30px; bottom: 26px; text-align: right; }
  #weapon-name { font-size: 13px; letter-spacing: .12em; text-transform: uppercase; color: var(--muted); margin-bottom: 4px; }
  #ammo { display: flex; align-items: baseline; gap: 8px; justify-content: flex-end; font-family: var(--font-readout); }
  #ammo-mag { font-size: 52px; line-height: 1; }
  #ammo-reserve { font-size: 17px; color: var(--muted); }
  #grenade-row { display: flex; gap: 8px; justify-content: flex-end; margin-top: 10px; }
  .nade { min-width: 26px; height: 26px; padding: 0 6px; display: inline-flex; align-items: center; justify-content: center;
    border: 1px solid var(--hairline); border-radius: 5px; font-family: var(--font-readout); font-size: 13px; color: var(--ink);
    background: color-mix(in srgb, var(--panel) 80%, transparent); }
  .nade.sel { border-color: var(--accent); color: var(--accent); }
  .nade.empty { opacity: .3; }
  #bomb-icon { margin-right: 8px; font-size: 13px; color: var(--accent); opacity: .25; transition: opacity 200ms; }

