  /* Progress (plant/defuse) under crosshair. */
  #progress-wrap { position: fixed; left: 50%; top: 56%; transform: translateX(-50%); width: 220px; opacity: 0; transition: opacity 120ms; text-align: center; }
  #progress-label { font-family: var(--font-readout); font-size: 12px; letter-spacing: .18em; color: var(--accent); }
  #progress-track { margin-top: 6px; height: 4px; background: rgba(255,255,255,.12); border-radius: 2px; overflow: hidden; }
  #progress { height: 100%; width: 0%; background: var(--accent); }

  #fps { position: fixed; top: 12px; left: 16px; font-family: var(--font-readout); font-size: 11px; color: var(--muted); opacity: .7; }

  /* Buy menu. */
  #buy-menu { position: fixed; left: 50%; top: 50%; transform: translate(-50%,-50%); width: 560px; max-width: 92vw;
    background: color-mix(in srgb, var(--panel) 96%, transparent); border: 1px solid var(--hairline); border-radius: 8px;
    padding: 22px; display: none; pointer-events: auto; }
  #buy-menu.open { display: block; }
  #buy-menu h2 { margin: 0 0 4px; font-size: 20px; letter-spacing: .06em; }
  #buy-menu .buy-hint { margin: 0 0 16px; font-size: 13px; color: var(--muted); }
  #buy-list { display: flex; flex-direction: column; gap: 6px; }
  .buy-row { display: grid; grid-template-columns: 30px 1fr auto auto; align-items: center; gap: 12px;
    padding: 9px 12px; background: rgba(255,255,255,.03); border: 1px solid var(--hairline); border-radius: 6px;
    color: var(--ink); font: inherit; font-size: 14px; text-align: left; cursor: pointer; }
  .buy-row:hover { border-color: var(--accent); background: rgba(255,122,26,.08); }
  .buy-row.dim { opacity: .45; cursor: default; }
  .buy-row.active { border-color: var(--good); }
  .buy-key { font-family: var(--font-readout); color: var(--muted); font-size: 12px; }
  .buy-name { font-weight: 600; letter-spacing: .02em; }
  .buy-stat { font-family: var(--font-readout); font-size: 11px; color: var(--muted); }
  .buy-price { font-family: var(--font-readout); color: var(--accent); font-size: 13px; }
  #buy-close { margin-top: 14px; width: 100%; padding: 10px; font: inherit; font-weight: 600; letter-spacing: .08em;
    background: var(--accent); color: #14100a; border: 0; border-radius: 6px; cursor: pointer; }
  #buy-close:hover { background: #ffa050; }

  /* Overlay (menu / pause / end). */
  .overlay { position: fixed; inset: 0; display: grid; place-items: center; padding: 24px;
    background: color-mix(in srgb, var(--canvas) 78%, transparent); backdrop-filter: blur(3px); z-index: 10; }
  .overlay.hidden { display: none; }
  .panel { width: min(520px, 100%); padding: 36px; background: var(--panel); border: 1px solid var(--hairline); border-radius: 10px; }
  .panel h1 { margin: 0 0 6px; font-size: 40px; line-height: 1.05; font-weight: 700; letter-spacing: .02em; }
  .panel h1 span { color: var(--accent); }
  .panel p { margin: 0 0 24px; font-size: 15px; line-height: 1.55; color: var(--muted); }
  #play { font: inherit; font-weight: 600; padding: 13px 22px; border: 1px solid var(--accent); border-radius: 8px;
    background: var(--accent); color: #14100a; cursor: pointer; letter-spacing: .04em; }
  #play:hover { background: #ffa050; border-color: #ffa050; }
  .keys { margin: 26px 0 0; padding: 0; list-style: none; display: grid; grid-template-columns: 1fr 1fr; gap: 9px 18px; font-size: 13px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 8px; }
  .keys kbd { min-width: 26px; padding: 3px 7px; border: 1px solid var(--hairline); border-radius: 5px;
    font-family: var(--font-readout); font-size: 11px; color: var(--ink); text-align: center; background: rgba(255,255,255,.03); }

  @media (prefers-reduced-motion: reduce) {
    #hitmarker, #vignette, .feed-row { transition-duration: .01ms; animation: none; }
  }
</style>
</head>
