  solid(6, 0.4, -32, 2.2, 2.0, 2.2, mats.metal);
  solid(0, 0.4, -35, 3, 2.6, 1.6, mats.rust);
  solid(-9, 0.4, -26, 1.6, 1.4, 1.6, mats.metal);
  solid(9, 0.4, -26, 1.6, 1.4, 1.6, mats.metal);
  // plaza low walls giving partial cover
  solid(-11, 0, -30, 1, 1.1, 18, mats.concrete);
