  // plaza south entrance walls (gap in the middle = chute from mid)
  solid(-4.5, 0, -20.5, 4, 3.4, 1, mats.concrete);
  solid(4.5, 0, -20.5, 4, 3.4, 1, mats.concrete);
  // west/east entrances into the plaza
  solid(-16, 0, -20, 6, 3.4, 1, mats.concrete);
