  // ---- Connector walls shaping lanes ------------------------------------------
  solid(-14.5, 0, 30, 1, 3.6, 12, mats.concrete);    // yard/hall divider south
  solid(14.5, 0, 30, 1, 3.6, 12, mats.concrete);
