  solid(14.5, 0, -14, 1, 3.6, 8, mats.concrete);

  // ---- Skyline dressing (non-colliding, above walls) --------------------------
  for (let i = 0; i < 9; i += 1) {
    const x = -38 + i * 9.5;
    const h = 9 + ((i * 7) % 13);
    const w = 6 + ((i * 5) % 7);
